import type { Timeline } from './timing.ts';

/** Render `src/voice-timing.ts` for the Motion Canvas project. */
export function renderVoiceTimingTs(timeline: Pick<Timeline, 'actLengths' | 'total'>, projectName?: string): string {
  const header = [
    '// Auto-generated by NarraSync (Studio Audio Motion). Do not edit by hand.',
    projectName ? `// Project: ${projectName}` : null,
  ].filter(Boolean);
  return [
    ...header,
    `export const ACT_LENGTHS = [${timeline.actLengths.join(', ')}];`,
    `export const TOTAL_LENGTH = ${timeline.total};`,
    '',
  ].join('\n');
}
